import{_ as o,o as d,c,a0 as t}from"./chunks/framework.B27pdwYF.js";const h=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/architecture.md","filePath":"explanation/architecture.md"}'),a={name:"explanation/architecture.md"};function r(s,e,i,l,n,p){return d(),c("div",null,[...e[0]||(e[0]=[t('<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>Rust workspace, ports-and-adapters. <code>lasius-core</code> is pure domain (no I/O); <code>lasius-cli</code> is the composition root.</p><table tabindex="0"><thead><tr><th>Crate</th><th>Role</th></tr></thead><tbody><tr><td><code>crates/lasius-core</code></td><td><code>lasius.toml</code> model (incl. <code>provider</code>), provider kind, <code>gh repo list</code> JSON decoding, failure classification (<code>access-denied:</code>/<code>not-found:</code>), repo-name safety + exclude globs, <code>git status --porcelain=v2</code> parse/format, <code>*.code-workspace</code> generation — pure, unit-tested</td></tr><tr><td><code>crates/lasius-cli</code></td><td>the <code>lasius</code> engine lib — clap commands, <code>RepoProvider</code> seam (<code>providers.rs</code>, github via <code>gh</code> today), <code>std::process</code> for <code>git</code>/<code>gh</code>/<code>sh</code>, <code>std::fs</code> for the workspace, <code>std::thread::scope</code> parallelism. <strong>No bin</strong> — the <code>lasius</code> command is the tamias pack&#39;s generated <code>bins[]</code> shim → <code>tamias-driver-lasius cli</code> → <code>lasius::run_from</code> (T-012)</td></tr><tr><td><code>crates/lasius-driver</code></td><td><code>tamias-driver-lasius</code> — pavo driver: engine ops as <code>cli.&lt;verb&gt;</code> wire queries + <code>run</code>/<code>cli</code> engine passthroughs, <code>serve</code> ndjson loop, feature-gated <code>mcp</code></td></tr><tr><td><code>libraries/lasius</code></td><td>the tamias pack — <code>tamias.yaml</code> (<code>type: files</code>, <code>bins: [{name: lasius, shim: cli, driver: lasius}]</code>); <code>cargo xtask pack</code> stages <code>drivers/bin/&lt;triple&gt;/tamias-driver-lasius</code> (gitignored)</td></tr><tr><td><code>xtask</code></td><td><code>cargo xtask check</code> / <code>test</code> / <code>coverage</code> / <code>pack</code> / <code>install</code> / <code>fmt</code></td></tr></tbody></table><h2 id="data-flow" tabindex="-1">Data flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data flow&quot;">​</a></h2><p>Provider discovery (<code>provider = &quot;github&quot;</code> → <code>gh repo list --json</code>) → decode + filter (archived, private, exclude globs, unsafe names) → <code>git clone</code> into <code>repos_dir</code> → scan local clones for status/update/workspace-file generation.</p><p><code>status</code>/<code>update</code>/<code>code-workspace generate</code> iterate the local clones, not the provider&#39;s repo list — a manually added clone is managed too, and a repo deleted upstream still gets pulled until removed.</p><p>Per-repo failures never abort a batch: <code>clone</code>/<code>update</code>/<code>status</code> collect them and report at the end, with stderr classified (<code>access-denied:</code>, <code>not-found:</code>) so credential and permission problems are obvious. <code>check</code> adds <code>remote-reachable</code>, which probes each clone&#39;s <code>origin</code> via <code>git ls-remote</code> with credential prompts disabled and a 20s timeout, so a hung network can&#39;t stall the run.</p><h2 id="safety" tabindex="-1">Safety <a class="header-anchor" href="#safety" aria-label="Permalink to &quot;Safety&quot;">​</a></h2><ul><li>Repo names from <code>gh</code> are validated before they become path segments.</li><li><code>rm</code> refuses dirty trees, unpushed commits, stashes, linked worktrees, nested <code>.git</code> dirs, and extra remotes unless <code>--force</code>.</li><li>Generated files (<code>*.code-workspace</code>) and <code>repos/</code> are gitignored — the workspace repo tracks config and docs only.</li></ul>',9)])])}const m=o(a,[["render",r]]);export{h as __pageData,m as default};
